72→test("hide mode refuses an empty list or an id outside the baseline", () => {
73→  assert.throws(() => planVisibility({ mode: "hide", baseline, current: {}, hide: [] }), /at least one/);
74→  assert.throws(() => planVisibility({ mode: "hide", baseline, current: {}, hide: ["skl-nope"] }), /not in the baseline/);
