197→  const decoyIds = new Set(decoyArg ? JSON.parse(readFileSync(decoyArg.slice(9), "utf8")).map((d) => d.asset_id ?? d) : []);
198→  const result = allAuthors(events, { decoyIds });
199→  console.log(args.includes("--json") ? JSON.stringify(result, null, 2) : renderAuthors(result));
200→}
