131→
132→  /** 读取资源字节；不存在 → null。 */
133→  async readResource(
134→    skillId: string,
135→    version: number,
136→    path: string,
137→    encoding: "utf-8" | "base64",
138→  ): Promise<SkillResourceReadResult | null> {
139→    this.assertPath(path);
140→    const key = this.fileKey(skillId, version, path);
141→    const buf = await this.storage.readFileBuffer(key);
142→    if (!buf) return null;
143→    return {
144→      path,
145→      content: encoding === "base64" ? buf.toString("base64") : buf.toString("utf-8"),
146→      encoding,
147→      size_bytes: buf.length,
148→      mime_type: guessMime(path),
149→      is_executable: false, // 不从 storage 元数据反推（local-fs 与 COS 行为不一致）
150→      version,
