167→    const prefix = this.filesPrefix(skillId, version);
168→    const result = await this.storage.getBackend().listObjects(prefix, {
169→      recursive: true,
170→      maxKeys: 100_000,
171→    });
172→    const out: SkillManifestEntry[] = [];
173→    for (const e of result.entries) {
174→      if (e.isDirectory) continue;
175→      const path = e.key.startsWith(prefix) ? e.key.slice(prefix.length) : e.key;
176→      // 读元数据拿到 is_executable / contentType（开销比读字节小很多）
177→      const obj = await this.storage.getBackend().getObject(e.key);
178→      const isExec = obj?.metadata?.is_executable === "1";
179→      const mime = obj?.contentType ?? guessMime(path);
180→      out.push({
181→        path,
182→        size_bytes: e.size,
183→        mime_type: mime,
184→        is_executable: isExec,
